(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.02+t*0.3)*15 + Math.cos(y*0.015-t*0.2)*10;
  const w1y = Math.cos(y*0.02-t*0.25)*15 + Math.sin(x*0.018+t*0.35)*10;
  const sx = x+w1x, sy = y+w1y;
  const w2x = Math.sin(sy*0.025+t*0.15)*8 + Math.cos(sx*0.03-t*0.4)*6;
  const w2y = Math.cos(sx*0.022+t*0.18)*8 + Math.sin(sy*0.028-t*0.35)*6;
  const fx = sx+w2x, fy = sy+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.9],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.1],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.85],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 1.05],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.95],
    [80+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65+1)*50, 0.11, 2.1, 0.88],
    [400+Math.cos(t*0.55+2)*60, 200+Math.sin(t*0.75+4)*40, 0.05, 2.8, 1.15]
  ];
  let aS=0, iS=0, cS=0;
  for (const [sX,sY,f,sp,w] of src) {
    const d = Math.sqrt((fx-sX)**2+(fy-sY)**2);
    aS += Math.sin(d*f - t*sp)*w;
    iS += Math.sin(d*f*0.7 + t*sp*0.6 + 1.5)*w;
    cS += Math.cos(d*f*0.5 - t*sp*0.8 + 3.0)*w*0.4;
  }
  const n = src.length;
  const act = aS/n, inh = iS/n, crs = cS/n;
  const bg = (Math.sin(fx*0.04+fy*0.025+t*0.8)+Math.sin(fx*0.03-fy*0.04+t*1.1))/2 + Math.sin((fx+fy)*0.12+t*2.5)*0.2 + Math.sin((fx-fy)*0.1-t*2)*0.2;
  const dist = Math.sqrt((fx-cx)**2+(fy-cy)**2), ang = Math.atan2(fy-cy, fx-cx);
  const sp1 = (Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4;
  const sp2 = (Math.sin(dist*0.08+ang*2-t*2.0)+Math.cos(dist*0.06-ang*5-t*1.8))*0.2;
  const sp3 = Math.sin(dist*0.03-ang*7+t*0.9)*0.15;
  const spiral = sp1+sp2+sp3;
  const turb = Math.sin(fx*0.07+t*1.3)*Math.sin(fy*0.09-t*0.9)*Math.cos((fx+fy)*0.05+t*0.7)*0.3;
  const cell1 = Math.tanh((Math.sin(fx*0.15)*Math.sin(fy*0.15)+Math.sin((fx+fy)*0.1+t)*0.5)*1.5)*0.3;
  const cell2 = Math.sin(Math.sin(fx*0.08)*3+Math.sin(fy*0.08)*3+t*0.5)*0.15;
  const cell = cell1+cell2;
  const react1 = Math.tanh((act - inh*0.7 + bg*0.3 + spiral)*2.2);
  const react2 = Math.tanh((crs + turb + spiral*0.5 - act*0.3)*1.8);
  const reaction = react1*0.7 + react2*0.3;
  const blend = reaction*0.6 + cell*0.25 + turb*0.15, v = blend*0.5+0.5;
  const pal = [[5,12,45],[10,45,85],[15,90,120],[25,140,135],[80,175,120],[180,190,70],[210,155,55],[195,95,60],[160,50,55],[100,25,50],[45,15,40],[5,12,45]];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const lum = 0.75+Math.sin(reaction*Math.PI)*0.25;
  const edge = Math.abs(reaction)>0.75?1.2:Math.abs(reaction)>0.5?1.05:0.95;
  const glow = Math.max(0, 1.0-dist/280)*0.15;
  return [
    Math.min(255, ((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge+glow*40)|0),
    Math.min(255, ((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge+glow*60)|0),
    Math.min(255, ((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge+glow*80)|0)
  ];
}
